/* The Steam Controller: Valve, wired, Bluetooth, through its receiver (as
 * SDL knows them, controller_list.h) */
int
pad_kind(SDL_GamepadType type, uint16_t vendor, uint16_t product)
{
	static constexpr uint16_t STEAM_CONTROLLERS[] = { 0x1101, 0x1102, 0x1105, 0x1106, 0x1142 };

	if (vendor == 0x28de && std::find(std::begin(STEAM_CONTROLLERS), std::end(STEAM_CONTROLLERS), product) !=
	    std::end(STEAM_CONTROLLERS))
		return PAD_STEAM_CONTROLLER;
	return type;
}

const PadDrawing &
pad_drawing(int kind)
{
	if (kind == PAD_STEAM_CONTROLLER)
		return PAD_STEAM;
	switch (static_cast<SDL_GamepadType>(kind)) {
	case SDL_GAMEPAD_TYPE_XBOX360: return PAD_XBOX360;
	case SDL_GAMEPAD_TYPE_XBOXONE: return PAD_XBOXONE;
	case SDL_GAMEPAD_TYPE_PS3: return PAD_PS3;
	case SDL_GAMEPAD_TYPE_PS4: return PAD_PS4;
	case SDL_GAMEPAD_TYPE_PS5: return PAD_PS5;
	case SDL_GAMEPAD_TYPE_NINTENDO_SWITCH_PRO:
	case SDL_GAMEPAD_TYPE_NINTENDO_SWITCH_JOYCON_PAIR: return PAD_SWITCH_PRO;
	/* A single Joy-Con has no drawing of its own: the generic one, with
	 * the names of its buttons still those of the Switch (menu_input) */
	default: return PAD_GENERIC;
	}
}

const char *
pad_drawing_name(int kind)
{
	const PadDrawing &drawing = pad_drawing(kind);

	if (&drawing == &PAD_XBOX360)
		return "Xbox 360";
	if (&drawing == &PAD_XBOXONE)
		return "Xbox One / Series";
	if (&drawing == &PAD_PS3)
		return "PlayStation 3";
	if (&drawing == &PAD_PS4)
		return "PlayStation 4";
	if (&drawing == &PAD_PS5)
		return "PlayStation 5";
	if (&drawing == &PAD_SWITCH_PRO)
		return "Switch Pro";
	if (&drawing == &PAD_STEAM)
		return "Steam Controller";
	return "Generic";
}

